// ---- _shared/loyalty.ts
// Loyalty rules shared by the Edge Functions, the app and the tests.
// Plain TypeScript with no imports so it runs unchanged in Deno, Node (type stripping) and Metro.

type ProgramType = 'stamps' | 'points';
type CardStatus = 'active' | 'complete' | 'redeemed';

type ProgramRules = {
  type: ProgramType;
  /** Stamps or points needed for the reward. */
  goal: number;
  /** Stamps (usually 1) or points added per eligible purchase. */
  step: number;
  /** Minimum time between two collections on the same card. */
  cooldownMinutes: number;
};

type CardState = {
  current: number;
  status: CardStatus;
  /** Last collection on this card, ISO string or null. */
  lastCollectedAt: string | null;
};

const DEFAULT_COOLDOWN_MINUTES = 120;

/** Per-user limits across all businesses: protects against scripted scanning. */
const RATE_LIMITS = [
  { windowMinutes: 1, max: 3 },
  { windowMinutes: 60, max: 12 },
] as const;

type CollectDecision =
  | { kind: 'apply'; current: number; added: number; status: CardStatus; completed: boolean }
  | { kind: 'cooldown'; retryAt: string; remainingMinutes: number }
  | { kind: 'complete' }
  | { kind: 'redeemed' };

/** Decide what one collection does to a card. Pure: the caller persists the result. */
function decideCollect(rules: ProgramRules, card: CardState, now: Date): CollectDecision {
  if (card.status === 'redeemed') return { kind: 'redeemed' };
  if (card.status === 'complete' || card.current >= rules.goal) return { kind: 'complete' };

  if (card.lastCollectedAt) {
    const cooldownMs = Math.max(0, rules.cooldownMinutes) * 60_000;
    const retry = new Date(card.lastCollectedAt).getTime() + cooldownMs;
    if (retry > now.getTime()) {
      return {
        kind: 'cooldown',
        retryAt: new Date(retry).toISOString(),
        remainingMinutes: Math.ceil((retry - now.getTime()) / 60_000),
      };
    }
  }

  const step = Math.max(1, Math.floor(rules.step));
  const current = Math.min(rules.goal, card.current + step);
  const completed = current >= rules.goal;
  return { kind: 'apply', current, added: current - card.current, status: completed ? 'complete' : 'active', completed };
}

/** True when the user already reached a per-user limit. `recent` holds the times of their latest collections. */
function isRateLimited(recent: readonly string[], now: Date, limits = RATE_LIMITS): boolean {
  return limits.some(({ windowMinutes, max }) => {
    const from = now.getTime() - windowMinutes * 60_000;
    return recent.filter((t) => new Date(t).getTime() > from).length >= max;
  });
}

/** How many stamps or points are still missing. */
function remaining(rules: Pick<ProgramRules, 'goal'>, current: number): number {
  return Math.max(0, rules.goal - current);
}

/** Progress between 0 and 1. */
function progress(rules: Pick<ProgramRules, 'goal'>, current: number): number {
  if (rules.goal <= 0) return 1;
  return Math.min(1, Math.max(0, current / rules.goal));
}

/** Wallet order: ready rewards first, then the card closest to its reward, then the newest. */
function sortWallet<T extends { current: number; goal: number; status: CardStatus; createdAt: string }>(cards: readonly T[]): T[] {
  return [...cards].sort((a, b) => {
    const ra = a.status === 'complete' ? 0 : 1 - progress(a, a.current);
    const rb = b.status === 'complete' ? 0 : 1 - progress(b, b.current);
    if (ra !== rb) return ra - rb;
    return b.createdAt.localeCompare(a.createdAt);
  });
}

/** Redemption is only possible on a complete card. */
function canRedeem(card: Pick<CardState, 'status' | 'current'>, rules: Pick<ProgramRules, 'goal'>): boolean {
  return card.status === 'complete' || (card.status === 'active' && card.current >= rules.goal);
}

/** Hebrew copy for the missing amount, e.g. "עוד 3 חותמות להטבה". */
function remainingLabel(type: ProgramType, missing: number): string {
  if (missing <= 0) return 'ההטבה מוכנה';
  if (type === 'points') return `עוד ${missing} נק׳ להטבה`;
  if (missing === 1) return 'עוד חותמת אחת להטבה';
  return `עוד ${missing} חותמות להטבה`;
}

/** Hebrew duration for the cooldown message, e.g. "שעה ו-20 דקות". */
function durationLabel(minutes: number): string {
  const m = Math.max(1, Math.ceil(minutes));
  const h = Math.floor(m / 60);
  const rest = m % 60;
  const hours = h === 0 ? '' : h === 1 ? 'שעה' : h === 2 ? 'שעתיים' : `${h} שעות`;
  const mins = rest === 0 ? '' : rest === 1 ? 'דקה' : `${rest} דקות`;
  if (hours && mins) return `${hours} ו-${mins}`;
  return hours || mins;
}

function cooldownMessage(remainingMinutes: number): string {
  return `כבר נאספה חותמת, אפשר שוב בעוד ${durationLabel(remainingMinutes)}`;
}

/** Normalise an Israeli mobile number to E.164 (+9725XXXXXXXX). Returns null when it is not a mobile number. */
function normalizeIsraeliPhone(input: string): string | null {
  let digits = input.replace(/[^\d+]/g, '');
  if (digits.startsWith('+972')) digits = '0' + digits.slice(4);
  else if (digits.startsWith('972')) digits = '0' + digits.slice(3);
  if (!/^05\d{8}$/.test(digits)) return null;
  return '+972' + digits.slice(1);
}

/** Trim and lower-case an email address. Returns null when it does not look like one. */
function normalizeEmail(input: string): string | null {
  const v = input.trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v) && v.length <= 254 ? v : null;
}

/** Show an E.164 Israeli number the local way: 050-123-4567. */
function formatIsraeliPhone(e164: string): string {
  const local = e164.startsWith('+972') ? '0' + e164.slice(4) : e164;
  if (!/^05\d{8}$/.test(local)) return e164;
  return `${local.slice(0, 3)}-${local.slice(3, 6)}-${local.slice(6)}`;
}

/** Wrong staff PINs allowed per customer, business and day (consecutive). Same as pin_max_failures() in SQL. */
const PIN_MAX_FAILURES = 3;

/** "נשארו 2 ניסיונות" under a wrong PIN. */
function wrongPinMessage(attemptsLeft: number): string {
  if (attemptsLeft <= 0) return 'הקוד שגוי';
  if (attemptsLeft === 1) return 'הקוד שגוי. נשאר ניסיון אחד';
  return `הקוד שגוי. נשארו ${attemptsLeft} ניסיונות`;
}

/** Shown when the customer is locked out at a business until midnight. */
function lockedMessage(): string {
  return 'יותר מדי קודים שגויים. אפשר לנסות שוב מחר';
}

// ---- _shared/token.ts
// Signed counter QR tokens and staff PIN hashes.
// Uses only WebCrypto, available in Deno (Edge Functions) and Node 20+ (admin script, tests).
// The secrets never reach the app: the app only scans and forwards the payload.

/** Scheme printed in the counter QR. Opening it with any camera app deep-links into Perko. */
const QR_PREFIX = 'perko://c/';

const enc = new TextEncoder();

function b64url(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function hmac(secret: string, message: string): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(message)));
}

/** Constant-time string comparison. */
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

async function qrSignature(secret: string, version: number, qrId: string): Promise<string> {
  // 16 bytes of the HMAC (128 bits) keep the printed code small and are plenty against guessing.
  return b64url((await hmac(secret, `perko.qr.v${version}.${qrId.toLowerCase()}`)).slice(0, 16));
}

/** Build the payload printed on a business's counter code. */
async function signQrPayload(secret: string, version: number, qrId: string): Promise<string> {
  if (!UUID.test(qrId)) throw new Error('qrId must be a uuid');
  return `${QR_PREFIX}v${version}.${qrId.toLowerCase()}.${await qrSignature(secret, version, qrId)}`;
}

type ParsedQr = { version: number; qrId: string; signature: string };

/** Parse without verifying. Returns null for anything that is not a Perko counter code. */
function parseQrPayload(payload: string): ParsedQr | null {
  const raw = payload.trim();
  if (!raw.startsWith(QR_PREFIX)) return null;
  const m = /^v(\d{1,3})\.([0-9a-f-]{36})\.([A-Za-z0-9_-]{22})$/.exec(raw.slice(QR_PREFIX.length));
  if (!m || !UUID.test(m[2])) return null;
  return { version: Number(m[1]), qrId: m[2].toLowerCase(), signature: m[3] };
}

/**
 * Verify a scanned payload. `secrets` maps key version to secret so codes can be rotated:
 * print new codes with a new version, keep the old secret until the old codes are collected, then drop it.
 */
async function verifyQrPayload(payload: string, secrets: Record<number, string>): Promise<ParsedQr | null> {
  const parsed = parseQrPayload(payload);
  if (!parsed) return null;
  const secret = secrets[parsed.version];
  if (!secret) return null;
  const expected = await qrSignature(secret, parsed.version, parsed.qrId);
  return safeEqual(expected, parsed.signature) ? parsed : null;
}

/** Staff PINs are 4 digits, typed by a staff member on the customer's phone. */
const PIN_LENGTH = 4;

function isPinFormat(pin: unknown): pin is string {
  return typeof pin === 'string' && /^\d{4}$/.test(pin);
}

function hex(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += b.toString(16).padStart(2, '0');
  return s;
}

/**
 * What the database stores for a staff PIN: HMAC-SHA256 keyed with PIN_SECRET over the business id and the PIN.
 * Without the secret a leaked table cannot be brute-forced (10,000 PINs would take a moment with a plain hash).
 * The business id makes the same PIN in two businesses look unrelated.
 */
async function hashPin(secret: string, businessId: string, pin: string): Promise<string> {
  if (!isPinFormat(pin)) throw new Error('a PIN is 4 digits');
  return hex(await hmac(secret, `perko.pin.${businessId.toLowerCase()}.${pin}`));
}

/** PINs a guesser tries first: one digit repeated (0000) and runs (1234, 9876). */
function isWeakPin(pin: string): boolean {
  if (/^(\d)\1{3}$/.test(pin)) return true;
  const d = [...pin].map(Number);
  const steps = d.slice(1).map((x, i) => x - d[i]);
  return steps.every((s) => s === 1) || steps.every((s) => s === -1);
}

/** A random PIN, never a weak one. Uses WebCrypto, so it is unpredictable. */
function randomPin(): string {
  for (;;) {
    const n = crypto.getRandomValues(new Uint32Array(1))[0];
    // 4,294,960,000 is a multiple of 10,000: dropping the top few values keeps every PIN equally likely.
    if (n >= 4_294_960_000) continue;
    const pin = String(n % 10_000).padStart(PIN_LENGTH, '0');
    if (!isWeakPin(pin)) return pin;
  }
}

// ---- _shared/api-types.ts
// Request and response shapes of the Edge Functions, shared with the app. No imports.


/** Where a collection came from. 'nfc' is reserved: v1 only sends 'qr'. */
type CollectSource = 'qr' | 'nfc';

/**
 * Collecting takes two calls. 'check' (no PIN) runs every test that does not need the staff member: the code,
 * the lockout, the rate limit and the cooldown, so the customer learns "come back later" before anyone types a
 * PIN. 'collect' repeats them with the 4-digit staff PIN and writes the stamp.
 */
type CollectRequest = { payload: string; source: CollectSource; action: 'check' | 'collect'; pin?: string };

type CollectedCard = {
  cardId: string;
  businessId: string;
  businessName: string;
  programName: string;
  type: ProgramType;
  goal: number;
  current: number;
  reward: string;
};

/** What the customer will get, shown above the PIN pad. The card may not exist yet (first scan). */
type PendingCollect = Omit<CollectedCard, 'cardId'> & { cardId: string | null; step: number };

type CollectResponse =
  | ({ status: 'ok'; added: number; completed: boolean } & CollectedCard)
  | { status: 'cooldown'; retryAt: string; remainingMinutes: number; businessName: string }
  | ({ status: 'complete' } & CollectedCard) // the card is already full: redeem first
  | ({ status: 'pin_required' } & PendingCollect) // check passed: show the PIN pad to the staff member
  | { status: 'wrong_pin'; attemptsLeft: number; businessName: string }
  | { status: 'locked'; until: string; businessName: string } // too many wrong PINs today at this business
  | { status: 'invalid' } // not a Perko code, bad signature, unknown code
  | { status: 'inactive' } // revoked code, or the business or program is paused
  | { status: 'rate_limited' };

/** A reward is used when a staff member types their PIN on the customer's phone. */
type RedeemRequest = { action: 'confirm'; cardId: string; pin: string };

type RedeemResponse =
  | { status: 'redeemed'; newCardId: string; reward: string }
  | { status: 'wrong_pin'; attemptsLeft: number }
  | { status: 'locked'; until: string } // too many wrong PINs today at this business
  | { status: 'not_ready' } // the card is not complete (or already redeemed)
  | { status: 'not_found' };

// business-admin: what the owner dashboard (and scripts/admin.ts with the service role key) can do.
type PinMode = 'shared' | 'per_staff';

type BusinessAdminRequest =
  | { action: 'pin_mode'; businessId: string; mode: PinMode } // switching to shared creates the team PIN
  | { action: 'team_pin'; businessId: string } // create or replace the team PIN (shared mode)
  | { action: 'staff_add'; businessId: string; name: string } // per_staff mode
  | { action: 'staff_remove'; businessId: string; staffPinId: string }
  | { action: 'pin_reset'; businessId: string; staffPinId: string }
  | { action: 'qr_list'; businessId: string }
  | { action: 'qr_create'; businessId: string; label?: string };

type CounterCode = { id: string; label: string | null; payload: string; createdAt: string };

type BusinessAdminResponse =
  | { status: 'ok' }
  | { status: 'pin'; staffPinId: string; name: string; pin: string } // the PIN is shown once, never stored in clear
  | { status: 'qr'; businessName: string; codes: CounterCode[] }
  | { status: 'forbidden' }
  | { status: 'invalid'; message: string };

// ---- _shared/server.ts
// Helpers for the Edge Functions (Deno). Not imported by the app.

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });
}

/** Service-role client: bypasses RLS, so every query below must filter by the verified user id. */
function admin(): SupabaseClient {
  return createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/** The signed-in user, from the Authorization header. */
async function requireUser(req: Request, db: SupabaseClient): Promise<{ id: string } | null> {
  const token = (req.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  if (!token) return null;
  const { data, error } = await db.auth.getUser(token);
  if (error || !data.user) return null;
  return { id: data.user.id };
}

/** QR secrets by key version, from QR_SECRET_V1, QR_SECRET_V2, ... */
function qrSecrets(): Record<number, string> {
  const out: Record<number, string> = {};
  for (const [k, v] of Object.entries(Deno.env.toObject())) {
    const m = /^QR_SECRET_V(\d+)$/.exec(k);
    if (m && v) out[Number(m[1])] = v;
  }
  return out;
}

function secret(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new Error(`missing secret ${name}`);
  return v;
}

/**
 * The caller of an owner action: a signed-in user, or the pilot admin script, which sends the service role key
 * itself (scripts/admin.ts pins:set, for businesses that have no owner yet).
 */
async function requireCaller(req: Request, db: SupabaseClient): Promise<{ service: true } | { service: false; id: string } | null> {
  const token = (req.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  if (token && serviceKey && token.length === serviceKey.length) {
    let diff = 0;
    for (let i = 0; i < token.length; i++) diff |= token.charCodeAt(i) ^ serviceKey.charCodeAt(i);
    if (diff === 0) return { service: true };
  }
  const user = await requireUser(req, db);
  return user ? { service: false, id: user.id } : null;
}

// ---- _shared/pins.ts
// Staff PINs on the server (Deno): checking a PIN typed at the counter and issuing new ones.
// The PIN itself is never stored, only hashPin() of it, keyed with PIN_SECRET.

type PinCheck =
  | { kind: 'ok'; staffPinId: string }
  | { kind: 'wrong'; attemptsLeft: number }
  | { kind: 'locked'; until: string };

/** Midnight in Israel when the customer is locked out at this business, else null. */
async function lockedUntil(db: SupabaseClient, userId: string, businessId: string): Promise<string | null> {
  const { data, error } = await db.rpc('pin_locked_until', { p_user: userId, p_business: businessId });
  if (error) throw new Error(`pin_locked_until: ${error.message}`);
  return (data as string | null) ?? null;
}

/**
 * Checks a PIN typed at the counter against the business's active PINs. A wrong PIN is logged; the last
 * allowed one locks the customer at this business until midnight and alerts the owner (register_pin_failure).
 * Call lockedUntil() first: a locked customer must not get another try.
 */
async function checkStaffPin(
  db: SupabaseClient, secret: string, userId: string, businessId: string, pin: unknown, context: 'collect' | 'redeem',
): Promise<PinCheck> {
  if (isPinFormat(pin)) {
    const { data } = await db
      .from('staff_pins')
      .select('id')
      .eq('business_id', businessId)
      .eq('pin_hash', await hashPin(secret, businessId, pin))
      .eq('active', true)
      .maybeSingle();
    if (data) return { kind: 'ok', staffPinId: data.id };
  }
  const { data: failures, error } = await db.rpc('register_pin_failure', { p_user: userId, p_business: businessId, p_context: context });
  if (error) throw new Error(`register_pin_failure: ${error.message}`);
  const n = Number(failures);
  if (n >= PIN_MAX_FAILURES) {
    return { kind: 'locked', until: (await lockedUntil(db, userId, businessId)) ?? new Date().toISOString() };
  }
  return { kind: 'wrong', attemptsLeft: PIN_MAX_FAILURES - n };
}

/** Creates an active PIN for a staff member (or "צוות") and returns it. It is shown once and never again. */
async function issuePin(db: SupabaseClient, secret: string, businessId: string, name: string): Promise<{ id: string; pin: string }> {
  // A PIN must be unique among the business's active PINs; with at most a few dozen staff a clash is rare.
  for (let i = 0; i < 25; i++) {
    const pin = randomPin();
    const { data, error } = await db
      .from('staff_pins')
      .insert({ business_id: businessId, name, pin_hash: await hashPin(secret, businessId, pin) })
      .select('id')
      .single();
    if (data) return { id: data.id, pin };
    if (error?.code !== '23505') throw new Error(`staff_pins: ${error?.message}`);
  }
  throw new Error('could not find a free PIN');
}

// ---- business-admin/index.ts
// POST /functions/v1/business-admin  { action, businessId, ... }
// Owner actions that need a server secret, called by the owner dashboard (dashboard/) and by scripts/admin.ts
// (with the service role key, for businesses without an owner). The caller must own the business.
//   pin_mode      'shared' (one code for the team) or 'per_staff'. Switching deactivates the other mode's PINs;
//                 switching to shared creates the team PIN and returns it.
//   team_pin      create or replace the team PIN (shared mode)
//   staff_add     a staff member with their own PIN (per_staff mode)
//   staff_remove  deactivate a staff member's PIN (kept for the log)
//   pin_reset     replace a PIN: the old row is deactivated, a new one is created under the same name
//   qr_list       the business's active counter codes, signed, for printing
//   qr_create     a new counter code
// A new PIN is returned once and never stored in clear. Program edits do not come here: owners edit their
// program directly under RLS (migration 20261031100200_business_members.sql).

const TEAM = 'צוות';

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ error: 'method' }, 405);

  const db = admin();
  const caller = await requireCaller(req, db);
  if (!caller) return json({ error: 'unauthorized' }, 401);

  let body: BusinessAdminRequest;
  try {
    body = await req.json();
  } catch {
    return json({ status: 'invalid', message: 'body' } satisfies BusinessAdminResponse, 400);
  }
  if (typeof body.businessId !== 'string' || !UUID.test(body.businessId)) {
    return json({ status: 'invalid', message: 'businessId' } satisfies BusinessAdminResponse, 400);
  }

  if (!caller.service) {
    const { data: member } = await db
      .from('business_members')
      .select('role')
      .eq('user_id', caller.id)
      .eq('business_id', body.businessId)
      .maybeSingle();
    if (member?.role !== 'owner') return json({ status: 'forbidden' } satisfies BusinessAdminResponse, 403);
  }

  const { data: business } = await db.from('businesses').select('id, name, pin_mode').eq('id', body.businessId).maybeSingle();
  if (!business) return json({ status: 'forbidden' } satisfies BusinessAdminResponse, 403);

  const deactivate = (q: { ids?: string[]; name?: string; except?: string } = {}) => {
    let u = db.from('staff_pins').update({ active: false }).eq('business_id', business.id).eq('active', true);
    if (q.ids) u = u.in('id', q.ids);
    if (q.name) u = u.eq('name', q.name);
    if (q.except) u = u.neq('name', q.except);
    return u;
  };
  const newPin = async (name: string): Promise<Response> => {
    const { id, pin } = await issuePin(db, secret('PIN_SECRET'), business.id, name);
    return json({ status: 'pin', staffPinId: id, name, pin } satisfies BusinessAdminResponse);
  };
  const invalid = (message: string) => json({ status: 'invalid', message } satisfies BusinessAdminResponse, 400);

  switch (body.action) {
    case 'pin_mode': {
      if (body.mode !== 'shared' && body.mode !== 'per_staff') return invalid('mode');
      if (body.mode === business.pin_mode) return json({ status: 'ok' } satisfies BusinessAdminResponse);
      await db.from('businesses').update({ pin_mode: body.mode }).eq('id', business.id);
      if (body.mode === 'per_staff') {
        // Staff PINs are added one by one; until then nobody can confirm at the counter.
        await deactivate({ name: TEAM });
        return json({ status: 'ok' } satisfies BusinessAdminResponse);
      }
      await deactivate();
      return newPin(TEAM);
    }

    case 'team_pin':
      if (business.pin_mode !== 'shared') return invalid('mode');
      await deactivate({ name: TEAM });
      return newPin(TEAM);

    case 'staff_add': {
      if (business.pin_mode !== 'per_staff') return invalid('mode');
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (name.length < 1 || name.length > 40 || name === TEAM) return invalid('name');
      return newPin(name);
    }

    case 'staff_remove':
    case 'pin_reset': {
      if (typeof body.staffPinId !== 'string' || !UUID.test(body.staffPinId)) return invalid('staffPinId');
      const { data: row } = await db
        .from('staff_pins')
        .select('id, name')
        .eq('id', body.staffPinId)
        .eq('business_id', business.id)
        .eq('active', true)
        .maybeSingle();
      if (!row) return invalid('staffPinId');
      await deactivate({ ids: [row.id] });
      return body.action === 'pin_reset' ? newPin(row.name) : json({ status: 'ok' } satisfies BusinessAdminResponse);
    }

    case 'qr_list':
    case 'qr_create': {
      const secrets = qrSecrets();
      const version = Math.max(...Object.keys(secrets).map(Number));
      if (!Number.isFinite(version)) return json({ error: 'qr secret' }, 500);
      if (body.action === 'qr_create') {
        const label = typeof body.label === 'string' ? body.label.trim().slice(0, 40) || null : null;
        await db.from('qr_codes').insert({ business_id: business.id, label, key_version: version });
      }
      const { data: rows } = await db
        .from('qr_codes')
        .select('id, label, key_version, created_at')
        .eq('business_id', business.id)
        .eq('active', true)
        .order('created_at');
      const codes: CounterCode[] = [];
      for (const q of rows ?? []) {
        // Codes signed with a removed key version no longer scan: they are left out.
        if (!secrets[q.key_version]) continue;
        codes.push({ id: q.id, label: q.label, payload: await signQrPayload(secrets[q.key_version], q.key_version, q.id), createdAt: q.created_at });
      }
      return json({ status: 'qr', businessName: business.name, codes } satisfies BusinessAdminResponse);
    }
  }
  return invalid('action');
});
